package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import org.apache.commons.lang3.ArrayUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class ClassUtils_toClass_TriageGen1Test {

    @Test
    public void testToClass_NullInput() {
        Class<?>[] result = ClassUtils.toClass(null);
        assertNull("If input is null, return value should be null", result);
    }

    @Test
    public void testToClass_EmptyArray() {
        Object[] input = new Object[0];
        Class<?>[] result = ClassUtils.toClass(input);
        assertArrayEquals("If input is empty array, return ArrayUtils.EMPTY_CLASS_ARRAY", 
                ArrayUtils.EMPTY_CLASS_ARRAY, result);
    }

    @Test
    public void testToClass_ValidObjects() {
        Object[] input = new Object[]{"string", 123, 45.67, true};
        Class<?>[] expected = new Class<?>[]{
                String.class,
                Integer.class,
                Double.class,
                Boolean.class
        };
        Class<?>[] result = ClassUtils.toClass(input);

        assertArrayEquals("The returned array should contain the classes of the input objects", expected, result);
    }

    @Test
    public void testToClass_MixedObjects() {
        Object[] input = new Object[]{new StringBuilder(), new java.util.ArrayList<String>()};
        Class<?>[] expected = new Class<?>[]{
                StringBuilder.class,
                java.util.ArrayList.class
        };
        Class<?>[] result = ClassUtils.toClass(input);

        assertArrayEquals("The returned array should handle different object types", expected, result);
    }

    @Test
    public void testToClass_SingleElement() {
        Object[] input = new Object[]{System.out};
        Class<?>[] expected = new Class<?>[]{java.io.PrintStream.class};
        Class<?>[] result = ClassUtils.toClass(input);

        assertArrayEquals("The returned array should handle single element arrays", expected, result);
        assertEquals("Length should be 1", 1, result.length);
    }
}
